const books = [
  { title: "Dune", year: 1965 },
  { title: "Neuromancer", year: 1984 },
  { title: "Foundation", year: 1951 },
];
$.each(books, (index, book) => {
  $("#books").append(`<li>${book.title} (${book.year})</li>`);
});
$("#books li").each( function(index) {
  if (books[index].year < 1970) {
    $(this).addClass("old");
  }
});

