questions.solution:
$( () => {
  $("#email_form").submit( evt => {
    let isValid = true;
    const email = $("#email").val().trim();
    const email2 = $("#email2").val().trim();
    const first = $("#first").val().trim();

    $("#email").next().text(email === "" ? "This field is required." : "");
    $("#email2").next().text(email2 !== email ? "Emails must match." : "");
    $("#first").next().text(first === "" ? "This field is required." : "");
    if (email === "" || email2 !== email || first === "") {
      isValid = false;
    }
    if (!isValid) {
      evt.preventDefault();
    }
  });
});

